const result = params.verificar_identidad;
const isRecord = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
const spokenString = (value) => typeof value === 'string' && value.trim().length > 0;
const unavailable = { ok: false, verificado: false, condiciones: null, code: 'IDENTITY_UNAVAILABLE', nextAction: null, remainingAttempts: null, question: null, mayEndCall: null };
const questions = {
  ASK_NAME: ['¿Me repite su nombre completo, por favor?', '¿Me dice solo su primer nombre, por favor?'],
  ASK_DOCUMENT: ['¿Me repite su cédula completa? Puede decirla seguida o en bloques.', '¿Me repite su número de cédula, por favor?', '¿Me repite su cédula completa, desde el primer dígito, con una pausa entre cada número?', 'Diga su cédula completa, número por número. Cuando termine, diga "terminé".'],
  REVIEW: ['No pude confirmar sus datos. Un asesor revisará su caso.']
};
let output = unavailable;
if (isRecord(result) && result.ok === true && typeof result.verificado === 'boolean' && Number.isInteger(result.remainingAttempts) && result.remainingAttempts >= 0 && result.remainingAttempts <= 2) {
  if (result.verificado === true) {
    const conditions = isRecord(result.condiciones) ? result.condiciones : null;
    const speech = conditions && conditions.speech;
    const hasSpeech = isRecord(speech) && ['initialPayment', 'installmentAmount', 'installmentCount', 'firstDueDate'].every((key) => spokenString(speech[key])) && Array.isArray(speech.installmentAmounts) && speech.installmentAmounts.length > 0 && speech.installmentAmounts.every(spokenString);
    if (hasSpeech && result.code === null && result.nextAction === 'CONTINUE' && result.question === null && result.mayEndCall === false) {
      output = { ok: true, verificado: true, condiciones: conditions, code: null, nextAction: 'CONTINUE', remainingAttempts: result.remainingAttempts, question: null, mayEndCall: false };
    }
  } else if (result.condiciones === null && ['IDENTITY_NOT_CONFIRMED', 'DOCUMENT_NOT_UNDERSTOOD'].includes(result.code)) {
    const action = result.nextAction;
    const asking = (action === 'ASK_NAME' || action === 'ASK_DOCUMENT') && result.remainingAttempts >= 1 && result.mayEndCall === false;
    const reviewing = action === 'REVIEW' && result.remainingAttempts === 0 && result.mayEndCall === true;
    const documentAction = result.code !== 'DOCUMENT_NOT_UNDERSTOOD' || action === 'ASK_DOCUMENT' || action === 'REVIEW';
    if ((asking || reviewing) && documentAction && questions[action].includes(result.question)) {
      output = { ok: true, verificado: false, condiciones: null, code: result.code, nextAction: action, remainingAttempts: result.remainingAttempts, question: result.question, mayEndCall: result.mayEndCall };
    }
  }
}
module.exports = output;
